<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {page} from '$app/state';import {listings,invoices,orders} from '$lib/api';import {session} from '$lib/stores/session';let item=$state<any>(null),error=$state(''),status=$state(''),ordering=$state(false),orderId=$state('');$effect(()=>{listings.one(page.params.id||'').then(v=>item=v).catch(e=>error=e.message)});let bolt11=()=>item?.bolt11||item?.invoice||'';async function orderAndPay(){if(ordering)return;ordering=true;try{const order=await orders.create(item.id,1);orderId=order.id;status='Order created. Opening Blink…';window.location.href=`lightning:${(order as any).bolt11||bolt11()}`}catch(e){error=e instanceof Error?e.message:'Unable to create order.'}finally{ordering=false}}async function verify(){try{const v=await invoices.verify(bolt11());status=v.settled?'Payment confirmed':'Awaiting settlement'}catch(e){error=e instanceof Error?e.message:'Unable to verify payment.'}}</script>
<PageShell eyebrow="LISTING DETAIL" title={item?.title||'Loading listing…'}>{#if error}<p class="alert">{error}</p>{:else if item}<div class="detail-grid"><div class="detail-art">{#if item.image}<img src={item.image} alt={item.title} />{:else}♻{/if}</div><div class="form-card"><p class="muted">{item.producerName}</p><p>{item.description}</p><h2>{Number(item.priceSats).toLocaleString()} sats</h2>{#if $session?.role?.toLowerCase()==='farmer'}<p class="state">Invoice from the Producer</p><div class="invoice-box">{#if bolt11()}<p class="eyebrow">PAYMENT INVOICE</p><img src={`https://quickchart.io/qr?text=${encodeURIComponent(`lightning:${bolt11()}`)}&size=220`} alt="Lightning invoice QR code"/><code>{bolt11()}</code>{:else}<p class="state">The Producer invoice is not available yet.</p>{/if}<button class="btn primary" onclick={orderAndPay} disabled={ordering||!!orderId||!bolt11()}>{ordering?'Preparing payment…':orderId?'Payment opened':'Pay invoice'}</button>{#if orderId}<button class="btn ghost" onclick={verify}>Verify payment</button>{/if}<p class="success">{status}</p></div>{/if}</div></div>{/if}</PageShell>
